const makeWritten = (id, label, clarify, starter, example) => ({
  id, label, clarify,
  steps: [
    'Read the question and underline the product, user or process it names.',
    'Select the strongest evidence from the theory section or your own project work.',
    'Explain how that evidence answers the question; do not only list it.',
    'Check that each claim is specific, believable and connected to the design brief.'
  ],
  starter, example
});

const makeSection = (title, html, facts, written) => ({ title, html, facts, written });

